-- Seed make / model / variant catalog from the Shrey car dataset.
-- Variant rows carry ex-showroom price and factory specs so later
-- vehicle submission can look a trim up. Used-vehicle price, km, and
-- colour stay on vehicles.
--
-- Cleanup applied while loading:
--   9 exact duplicate Mahindra XUV500 rows collapsed
--   "Land Rover Rover" + "Range*" repaired to Land Rover / Range Rover*
--   "Maruti Suzuki R" + "Wagon" repaired to Maruti Suzuki / Wagon R
--   Bmw, Mg, Dc, Icml stored as BMW, MG, DC, ICML
--   "Not Mentioned" body type and transmission stored as null
--   0 for height, length, width, seats, power, torque stored as null
--   Lexus NX 300H length 4.64 m stored as 4640 mm

alter table public.variants
  add column ex_showroom_price numeric(14,2),
  add column displacement_cc integer,
  add column cylinders smallint,
  add column fuel_tank_capacity_l numeric(6,1),
  add column fuel_type text,
  add column height_mm integer,
  add column length_mm integer,
  add column width_mm integer,
  add column body_type text,
  add column seating_capacity smallint,
  add column transmission text,
  add column power numeric(8,2),
  add column torque numeric(8,2),
  add constraint variants_fuel_type_check check (
    fuel_type is null
    or fuel_type in ('petrol', 'diesel', 'cng', 'electric', 'hybrid', 'cng_petrol')
  ),
  add constraint variants_transmission_check check (
    transmission is null
    or transmission in ('manual', 'automatic', 'amt', 'cvt', 'dct')
  );

create table private.catalog_import_staging (
  make_name text not null,
  model_name text not null,
  variant_name text not null,
  ex_showroom_price numeric(14,2) not null,
  displacement_cc integer,
  cylinders smallint,
  fuel_tank_capacity_l numeric(6,1),
  fuel_type text,
  height_mm integer,
  length_mm integer,
  width_mm integer,
  body_type text,
  seating_capacity smallint,
  transmission text,
  power numeric(8,2),
  torque numeric(8,2)
);

