insert into public.makes (name)
select distinct make_name
from private.catalog_import_staging
on conflict (name) where deleted_at is null do nothing;

insert into public.models (make_id, name)
select mk.id, src.model_name
from (
  select distinct make_name, model_name
  from private.catalog_import_staging
) src
join public.makes mk
  on mk.name = src.make_name
 and mk.deleted_at is null
on conflict (make_id, name) where deleted_at is null do nothing;

insert into public.variants (
  model_id,
  name,
  ex_showroom_price,
  displacement_cc,
  cylinders,
  fuel_tank_capacity_l,
  fuel_type,
  height_mm,
  length_mm,
  width_mm,
  body_type,
  seating_capacity,
  transmission,
  power,
  torque
)
select
  mo.id,
  src.variant_name,
  src.ex_showroom_price,
  src.displacement_cc,
  src.cylinders,
  src.fuel_tank_capacity_l,
  src.fuel_type,
  src.height_mm,
  src.length_mm,
  src.width_mm,
  src.body_type,
  src.seating_capacity,
  src.transmission,
  src.power,
  src.torque
from private.catalog_import_staging src
join public.makes mk
  on mk.name = src.make_name
 and mk.deleted_at is null
join public.models mo
  on mo.make_id = mk.id
 and mo.name = src.model_name
 and mo.deleted_at is null;

drop table private.catalog_import_staging;
